-- Sovietski: the SU-56 Shockwave heavy tank and the SU-58 Tunguska super-tank (printed 197-203).
-- 2 vehicle rows, with 41 locations and 12 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~391-sovietski-v6.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('su-56-shockwave', 'SU-56 Shockwave Heavy Tank', 'rifts', 'vehicle', 'Six: a Tank Commander, a Tank Driver, a Tank Specialist and three gunners.', 'None.', '90 mph (144 km) top; 50 mph (80 km) cruising and off-road. Range effectively unlimited.', 'None.', 'Not amphibious; wades in water as deep as 6 feet (1.8 m) with no trouble.', 'Height 10 feet (3 m), the lower hull only 6 feet (1.8 m); width 14 feet (4.3 m), length 30 feet (9.1 m).', '36 tons', 440, 1, NULL, 29000000, '29 million credits, Sovietski military only and not on the Black Market. A captured one in good shape can fetch as much as 36 million credits.', 'One of the two workhorses of the Sovietski Tank Corps, alongside the SU-52 Groundthunder of Mystic Russia; both are quick armored cavalry with strong firepower, posted all over Sovietski lands and along the borders. The Shockwave is big but squat, with a low turret. Its 100 mm main gun is smaller than the Groundthunder''s 120 mm, a trade made so it could take a wider range of shells through a modern autoloader that swaps between ammunition types, and so it could carry more secondary weapons: a turret rail gun on its own backup power, two raising missile boxes, a double-barrel laser at the front right corner, laser guns at the other three corners, and mini-missile launchers that pop out of the hull sides at the rear. Two spare treads are carried; a trained crew fits one in the field in 1D4x10+30 minutes, an untrained one in twice that. Cargo: almost none, since crew space, the reactor and ammunition fill the hull. Nuclear, 20-year life. Standard Sovietski vehicle sensors.', 'Rifts World Book 36: Sovietski p.197-199'),
  ('su-58-tunguska', 'SU-58 Tunguska Super-Tank and Mobile Command Center', 'rifts', 'vehicle', '20: 1 Tank Commander, 2 Tank Drivers, 3 Tank Specialists and 14 gunners (4 on the plasma cannons, 8 at the rail gun stations, 1 on the twin main guns, 1 on the missiles).', 'Six in the turret''s command deck. The forward bay holds a combat squad: 11 Heavy Machines, 6 Superheavy Machines, 6 Red Squall flyers, or a mixed squad of 4 Heavy, 2 Superheavy and 2 Red Squall. Each of the two rear boxcars takes 40 fully equipped infantry or Light Machines, or 40 tons of cargo.', '60 mph (96 km) top; 45 mph (72 km) off-road, even across rubble or shelled ground.', 'None.', 'Not amphibious; rolls through water as deep as 7 feet (2.1 m) with no trouble.', 'Height 35 feet (10.7 m) overall: 28 feet (8.5 m) to the turret top, 25 feet (7.6 m) standing on a hatch, the sensor dome another 8 feet (2.4 m), and 28 feet (8.5 m) at the main sensor tower''s tip. 36 feet (11 m) wide and 68 feet (20.7 m) long.', '252 tons unloaded', 970, 1, NULL, NULL, 'The book gives no cost.', 'The newest and heaviest tank in the Sovietski Army, nicknamed the super tank, built from a pre-Rifts design recovered at a military research plant in Kaliningrad; one is reckoned worth a modern tank squad or a whole 20th Century tank company. Four track assemblies, each about the size of a tank, hang off the corners of a central weapons platform on armored, articulated joints and suspension that keep it level enough to fire across broken ground. The platform carries a ring of defensive turrets and, above them, a huge turret with twin 200mm cannons, medium-range and mini-missile launchers, and a command deck, so it works as a mobile command post or a defensive gun tower. A forward troop bay launches a squad of heavy machines or Red Squall platforms to keep enemies off it, and two boxcars at the back carry troops or freight. Its onboard computer, among the best in Russia, sets each track''s speed to the terrain, shifts the struts to keep the guns level, identifies enemy vehicles and monsters and suggests which to hit first; Triax engineers would like a look at it. At least a dozen are thought to be in service, three at Kaliningrad and two to four at Moscow, and the fleet is always in for repair: rumor says the computers and the giant shock absorbers give trouble. It usually leads a larger force, with a platoon of tanks or armored vehicles, Heavy or Superheavy Machines, or one or two squads of six Red Squalls assigned as escort on top of its own 6 to 11 troops. Inside: a cramped bunk room sleeping 8 in shifts, a commander''s office and lavatories. Cargo: lockers, the two boxcars, 10,000 gallons (37,854 liters) of water, a month of rations, a backpack, canteen, energy rifle and gear for every crew member, and eight jet packs. Nuclear, 20-year average life. Standard Sovietski sensors, plus six armored observation stations on the turret (each a 20 M.D.C. plexiglass window behind a shutter that flips up for direct viewing), communications at triple the usual range, and radar that tracks up to 144 targets at once out to 300 miles (480 km).', 'Rifts World Book 36: Sovietski p.199-203');

