  ('su-56-shockwave', 'Sensor Tower', 50, 'Turret. Small target: Called Shot only, -3 to strike.', 3),
  ('su-56-shockwave', '100 mm Main Gun', 150, NULL, 4),
  ('su-56-shockwave', 'Turret Rail Gun', 90, 'Top of the turret. Small target: Called Shot only, -3 to strike.', 5),
