  ('su-56-shockwave', 'Corner Lasers (3)', 50, 'Each; two at the back, one at the left front.', 7),
  ('su-56-shockwave', 'Missile Box Launchers (2)', 60, 'Each; back of the turret.', 8),
  ('su-56-shockwave', 'Pop-Up Mini-Missile Launchers (2)', 15, 'Each; hull sides. Small target: Called Shot only, -3 to strike.', 9),
  ('su-56-shockwave', 'Smoke Dispensers (4)', 8, 'Each; turret. Small target: Called Shot only, -3 to strike.', 10),
  ('su-56-shockwave', 'Spotlight', 10, 'Turret. Small target: Called Shot only, -3 to strike.', 11),
  ('su-56-shockwave', 'Main Hatch', 150, 'Front, top. Small target: Called Shot only, -3 to strike.', 12),
  ('su-56-shockwave', 'Treads (2)', 150, 'Each. Losing one: -50% speed, -20% piloting, -2 to dodge. Losing both immobilizes the tank.', 13),
  ('su-56-shockwave', 'Reinforced Crew Compartment', 200, 'Small target: Called Shot only, -3 to strike.', 14),
  ('su-56-shockwave', 'Main Body', 440, 'Depleting it shuts the tank down completely, rail gun, cannon and every laser included, and lays open the reinforced crew compartment.', 15),
  ('su-58-tunguska', 'Main Turret', 500, NULL, 1),
  ('su-58-tunguska', 'Main Cannons (2)', 230, 'Each; turret.', 2),
  ('su-58-tunguska', 'Medium-Range Missile Launchers (2)', 200, 'Each; turret.', 3),
  ('su-58-tunguska', 'Main Mini-Missile Launchers (2)', 80, 'Each; side of the turret. Small target: Called Shot only, -3 to strike.', 4),
  ('su-58-tunguska', 'Sensor Tower', 120, 'Turret. Small target: Called Shot only, -3 to strike.', 5),
  ('su-58-tunguska', 'Secondary Sensor Dome', 85, 'Turret. Small target: Called Shot only, -3 to strike.', 6),
  ('su-58-tunguska', 'Turret Hatches (3)', 100, 'Each; top of the turret.', 7),
  ('su-58-tunguska', 'Armor Observation Station Shielding (6)', 100, 'Each; turret. Small target: Called Shot only, -3 to strike. The sensor note gives these shutters 120 M.D.C. each; the location table''s 100 is kept.', 8),
  ('su-58-tunguska', 'Observation Windows (6)', 20, 'Each; exposed only when the armored shields are up. Small target: Called Shot only, -3 to strike.', 9),
  ('su-58-tunguska', 'Rail Gun and Flame Thrower Turrets (8)', 125, 'Each; below the main turret.', 10),
  ('su-58-tunguska', 'Plasma Cannon Turrets (4)', 200, 'Each; one per tread assembly.', 11),
  ('su-58-tunguska', 'Tread Assembly/Tank Chassis (4)', 350, 'Each. Losing one: -20% speed and -5% piloting; each further assembly lost costs another 20% of speed and another -10% piloting. With all four gone the tank crawls on the hidden treads under the turret at 5 mph (8 km) at most; with those gone too it cannot move.', 12),
  ('su-58-tunguska', 'Treads on the Tread Assemblies (8)', 150, 'Each; two per tread assembly.', 13),
  ('su-58-tunguska', 'Side Access Blast Doors (2)', 200, 'Each. Small target: Called Shot only, -3 to strike.', 14),
  ('su-58-tunguska', 'Front Access Troop Blast Doors (2)', 200, 'Each. Small target: Called Shot only, -3 to strike.', 15),
  ('su-58-tunguska', 'Unfolding Ramps at Blast Doors (6)', 100, 'Each.', 16),
  ('su-58-tunguska', 'Communications Tower/Antenna', 100, 'Top of the turret. Small target: Called Shot only, -3 to strike. Destroying it loses the extended communications range.', 17),
  ('su-58-tunguska', 'Main Sensor Array', 80, 'Top of the turret. Small target: Called Shot only, -3 to strike. Destroying it cuts the turret''s long-range communications, radar and other senses; the four tread-assembly sensor units can still give basic targeting and friend-or-foe identification.', 18),
  ('su-58-tunguska', 'Independent Sensor Bubbles (4)', 25, 'Each; one per tread assembly. Small target: Called Shot only, -3 to strike. Only when these and the main array are all gone are optical aids and computer targeting lost; lookouts then report by radio with none of the sensor bonuses.', 19),
  ('su-58-tunguska', 'Armored Treads (12)', 150, 'Each; two per plasma unit and four under the main body.', 20),
  ('su-58-tunguska', 'Reinforced Crew Compartment of Turret/Command Deck', 400, 'Small target: Called Shot only, -3 to strike.', 21),
  ('su-58-tunguska', 'Reinforced Crew Compartments of Plasma Cannons (4)', 100, 'Each. Small target: Called Shot only, -3 to strike.', 22),
  ('su-58-tunguska', 'Reinforced Troop Compartments of Boxcars (2)', 100, 'Each; rear. Small target: Called Shot only, -3 to strike.', 23),
  ('su-58-tunguska', 'Reinforced Troop Compartment of Combat Squad', 150, 'Front. Small target: Called Shot only, -3 to strike.', 24),
  ('su-58-tunguska', 'Reinforced Crew Compartment of Main Body', 200, 'Center. Small target: Called Shot only, -3 to strike.', 25);

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('su-58-tunguska', 'Main Body', 970, 'Printed as Main Body of the Super-Tank. Depleting it shuts the vehicle down and silences every weapon on the main body and turret; the four tread-assembly plasma cannons can still fire.', 26);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('su-56-shockwave', 1, 'STG-45 High-Powered 100mm Cannon', 'Standard load: 20 solid slug (6D6 M.D., no blast radius), 18 high explosive anti-tank (1D4x10 M.D. to a 5 foot/1.5 m blast radius), 18 armor piercing (1D6x10, no blast radius; the book omits the unit) and 4 smoke (30 foot/9.1 m radius). Special rounds may be issued for the mission and the enemy expected.', 1, '5,600 feet (1,707 m)', 'Each shot uses one of the gunner''s melee attacks.', '60 rounds of mixed types.', NULL, 'The turret''s main gun, fed by an autoloader so its dedicated gunner can fire fast. Turret turns 360 degrees; the gun elevates and depresses 45 degrees. Anti-armor, then anti-monster.'),
  ('su-56-shockwave', 2, 'Turret Rail Gun', '2D6 M.D. per short 10 round burst, or 1D4x10 M.D. per full 40 round burst', 1, '4,000 feet (1,219 m)', 'Each burst, short or full, uses one melee attack.', '6,000 round drum: 150 full bursts or 600 short ones. A Tank Specialist swaps a drum in five minutes; anyone untrained takes 20.', NULL, 'On top of the turret, with an auxiliary power supply, so the gunner inside, the commander, or anyone by hand when the tank has lost power can work it. Turns 360 degrees with a 45 degree up and down arc. Anti-aircraft, anti-flyer and anti-missile, then anti-personnel and defense.'),
  ('su-56-shockwave', 3, 'Short-Range Missile Box Launchers (2)', 'Varies with the missile; usually 8 high explosive (medium: 2D6x10 M.D. to a 15 foot/4.6 m radius), 8 fragmentation (2D4x10 M.D. to a 20 foot/6.1 m radius) and two smoke', 1, 'High explosive 5 miles (8 km); fragmentation 3 miles (4.8 km)', 'One at a time or volleys of 2, 3, 4 or 6.', '16, eight per launcher.', NULL, 'One box on each side of the turret. To fire, each lifts 3 feet (0.9 m) and then turns 360 degrees with 60 degrees of up and down travel, independent of the main gun. Either the turret gunner or another gunner fires them, and they can be fired by hand when the tank is knocked out and without power, as long as the turret still has M.D.C. Anti-flyer and assault, then anti-missile and defense.'),
  ('su-56-shockwave', 4, 'Smoke Dispensers (4)', NULL, 0, 'A dense cloud covering an 80 foot (24 m) area ahead of or behind the tank, or the tank itself when it is stopped.', NULL, 'Four.', NULL, 'Two units on each side of the turret; they can release tear gas instead of smoke.'),
  ('su-56-shockwave', 5, 'Pop-Out Mini-Missile Launchers (2)', 'Varies with the missile; the standard issue is 7 high explosive (5D6 M.D. to a 5 foot/1.5 m blast radius), 7 plasma (1D6x10 M.D.) and 2 smoke, though any mini-missile fits. For non-lethal city assaults and riot work: 8 tear gas, 5 smoke and 2 high explosive for breaching barriers or doors. That listed mix is 16 missiles; the launchers hold 8.', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4, 6 or 8.', '8, four per launcher.', NULL, 'Hidden in the hull sides toward the rear until needed, and usually fired by the gunner who works the rear lasers. The book points to page 363 of Rifts Ultimate Edition for other missile types. Anti-flyer and anti-armor, then assault and defense.'),
  ('su-56-shockwave', 6, 'Forward Laser Turret', '6D6 M.D. per dual blast; it cannot fire a single blast', 1, '2,000 feet (610 m)', 'Each blast uses one melee attack.', 'Effectively unlimited.', NULL, 'A double-barrel laser at the front right corner, worked by the Tank Driver. It swings 40 degrees to either side and 20 degrees up and down. Anti-personnel and assault, then defense.'),
  ('su-56-shockwave', 7, 'Corner Laser Guns (3)', '2D6 M.D. per single laser blast; the rail gun some older tanks carry instead does 2D6 M.D. per 10 round burst and fires bursts only', 1, '2,000 feet (610 m), laser or rail gun', 'Each laser blast, or rail gun burst, uses one melee attack of its gunner.', 'A 2,000 round drum (200 bursts), which fits the rail gun version; the book gives no separate laser figure.', NULL, 'One at each of the three remaining corners. The front left gun usually has its own gunner, though any crew member can work it; one gunner runs both rear guns, aiming by video camera. Each traverses and elevates 20 degrees (printed as 20% degrees). Anti-personnel, then defense.'),
  ('su-58-tunguska', 1, 'SGT-70 High-Powered 200mm Cannons (2)', 'Standard load per cannon: 60 solid slug (1D6x10 M.D., no blast radius), 60 high explosive (1D6x10+10 M.D. to a 15 foot/4.6 m radius), 60 armor piercing (2D6x10 M.D., no blast radius), 40 high explosive anti-tank (2D6x10 M.D. to a 10 foot/3 m blast radius), 10 incendiary or other special rounds (silver, wood and the like) and 10 smoke (covers a 30 foot/9.1 m area). Double damage when both fire together at one target.', 1, '12,000 feet (3,658 m)', 'A single or paired blast costs the gunner one melee attack; the loading mechanism caps each cannon at five blasts per melee round.', '250, 125 per cannon; a destroyed cannon''s rounds can be routed to the other. The per-cannon load listed under damage adds up to 240.', NULL, 'Twin smoothbore guns in the main turret, loaded by hand or automatically from internal magazines. Turret turns 360 degrees; the guns elevate and depress 50 degrees. A dedicated gunner works them, or the Tank Commander. The book points to its tank round descriptions for the full ammunition details. Anti-armor, then assault.'),
  ('su-58-tunguska', 2, 'Medium-Range Missile Launchers (2)', 'Varies with the missile; any medium-range missile fits, usually high explosive (3D6x10 M.D. to a 30 foot/9.1 m blast radius), fragmentation (2D6x10 M.D. to a 40 foot/12.2 m radius) or armor piercing (3D6x10 M.D., no blast radius)', 1, 'Varies with the missile; usually 40 miles (64 km)', 'One at a time or volleys of 2, 4, 6 or 8.', '16, eight per launcher.', NULL, 'One on each side of the cannons toward the back of the turret, controlled by the pilot, for breaking fortifications, meeting air threats and hitting massed armor beyond normal range. Each can tilt through 200 degrees. The book points to page 363 of Rifts Ultimate Edition for other missile types. Anti-aircraft, then artillery barrage and anti-fortification.'),
  ('su-58-tunguska', 3, 'Mini-Missile Launchers (2)', 'Varies with the missile; one type or a mix of 2 to 4 types, never smoke. Usually high explosive (5D6 M.D. to a 5 foot/1.5 m blast radius) or fragmentation (5D6 M.D. to a 20 foot/6.1 m blast radius).', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4, 6, 8 or 12.', '48, 24 per launcher, plus one full reload for each. Reloading takes 1D6+4 minutes, done outside the hull by a Tank Specialist and two cyborgs flying on jet packs, so it is unwise under fire.', NULL, 'One beside and behind each medium-range launcher; each turns 360 degrees to fire up, down, ahead or behind. They guard the tank and wear down enemy infantry. Assault and defense, then anti-personnel.'),
  ('su-58-tunguska', 4, 'Defensive Rail Gun Turrets (8)', 'Rail gun: 4D6 M.D. per short 10 round burst. Flamethrower: 1D4x10 M.D. to anyone in its reach. Mini-missiles: usually all high explosive (5D6 M.D. to a 5 foot/1.5 m blast radius).', 1, 'Rail gun 4,000 feet (1,219 m); flamethrower 200 feet (61 m); mini-missiles one mile (printed as 16 km; a mile is 1.6 km)', 'A rail gun or flame burst costs the gunner one melee attack; mini-missiles go singly or in volleys of 2, 3 or 4, each launch one attack.', 'Per turret: a 6,000 round internal magazine (600 bursts), 20 flamethrower blasts, and four mini-missiles. The prose says each turret fires six mini-missiles; the payload line''s four is kept.', NULL, 'A ring of turrets at the base of the main turret, each with its own gunner, to beat off swarms (Brodkil, Gargoyles and many demons attack that way) and to shoot down incoming missile volleys. The flamethrower sits under each rail gun barrel to keep Warlord cyborgs and other ordinary troops off the turret and the main body; a gunner uses the rail gun or the flamethrower, not both at once. Each swings 45 degrees side to side and up and down. Defense, then anti-personnel.'),
  ('su-58-tunguska', 5, 'SPC-50 Heavy Plasma Cannons (4)', '1D6x10 M.D. per blast', 1, '2,000 feet (610 m)', 'Each blast uses one of the gunner''s melee attacks.', 'Effectively unlimited.', NULL, 'A short-barreled plasma turret on each of the four tread assemblies, which look like small tanks bolted to the corners of the main body and help drive it as well as fight. Each has its own gunner in a reinforced 100 M.D.C. compartment, turns 360 degrees and tilts 45 degrees up and down, and carries its own camera, sensor and targeting dome under the barrel plus the usual Sovietski combat systems, Cyberlink to its gunner among them. They keep firing after the main body is knocked out. Anti-armor and assault, then anti-monster and defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('su-56-shockwave', 'su-58-tunguska');
SELECT 'their 41 locations are in' AS assertion, count(*) AS got, 41 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('su-56-shockwave', 'su-58-tunguska');
SELECT 'their 12 weapon entries are in' AS assertion, count(*) AS got, 12 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('su-56-shockwave', 'su-58-tunguska');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('su-56-shockwave', 'su-58-tunguska') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~391-sovietski-v6.sql');
